#[test]
fn test_parse_upnp_duration() {
    assert_eq!(parse_upnp_duration("00:06:22.500"), Some(382.5));
    assert_eq!(parse_upnp_duration("01:00:00.000"), Some(3600.0));
    assert_eq!(parse_upnp_duration("invalid"), None);
}

